"use strict";function updateShiftDialog(){$("#dialog").dialog({modal:!0,width:"auto",height:230,dialogClass:"dialog-update-shift",title:"Shift on "+_event.start.format("MM/DD/YYYY"),open:function(){$("#current").text(_event.title)}})}var _event=null;$(document).ready(function(){var n=$("#EmployeeId").val();$("#defaultschedule").on("click",function(){document.location=_global.root+"employee/defaultschedule?employeeId="+n});$("#update").on("click",function(){$.post(_global.root+"Calendar/UpdateEmployeeShiftDate",{employeeId:n,date:_event.start.format("MM/DD/YYYY"),shiftId:$("#ShiftId").val()},function(){$("#row"+n).remove()});_event.title=$("#ShiftId option:selected").text();$("#calendar").fullCalendar("updateEvent",_event);$("#dialog").dialog("close")});$("#calendar").fullCalendar({theme:!0,header:{left:"prev",center:"title",right:"next"},editable:!1,events:function(t,i,r,u){$.ajax({url:_global.root+"Calendar/GetWorkingSchedule",dataType:"json",data:{date:$("#calendar").fullCalendar("getDate").format("MM/DD/YYYY"),employeeId:n},success:function(n){var t=[];$(n).each(function(n,i){var u=formatDate(new Date,"dd/MM/yyyy"),f=formatJsonDate(i.WorkDate),r=i.Title;u===f&&(r=r+" today");t.push({title:i.Title,start:formatJsonDate(i.WorkDate),className:r})});u(t)}})},eventClick:function(n){_event=n;updateShiftDialog();$("#calendar").fullCalendar("updateEvent",n)}})});